/**
 * @file eliteFourTrainerPreview.ts
 * Static preview data for Elite Four trainer dex UI (arena panel).
 */

import type { GameRuntime } from '../types/game.js';
import { getPokemonSpriteUrl } from './cardSprites.ts';
import { uiPokemonNameText } from '../ui/i18n.ts';
import { localizeTrainerName } from '../../constants/trainerNameI18n.ts';

export interface EliteFourPokemonPreview {
    name: string;
    displayName: string;
    spriteUrl: string;
    level: number;
}

export interface EliteFourTrainerPreview {
    championName: string;
    roleLabel: string;
    spriteUrl: string;
    specialtyType: string;
    team: EliteFourPokemonPreview[];
}

type EliteFourTrainerDef = {
    championName?: string;
    type?: string;
    team?: Array<{ name: string; level?: number }>;
};

type EliteFourDef = {
    trainers?: EliteFourTrainerDef[];
};

export function buildEliteFourTrainerPreviews(
    game: GameRuntime | null | undefined,
    eliteArenaId?: string | null,
): EliteFourTrainerPreview[] {
    if (!game) return [];
    const id = eliteArenaId ?? (typeof game.getEliteFourArenaIdForCurrentRegion === 'function'
        ? game.getEliteFourArenaIdForCurrentRegion()
        : 'elite_four_gen1');
    const eliteDef = (typeof game.getEliteFourDefinition === 'function'
        ? game.getEliteFourDefinition(id)
        : null) as EliteFourDef | null;
    if (!eliteDef?.trainers?.length) return [];

    return eliteDef.trainers
        .filter((trainer): trainer is EliteFourTrainerDef => Boolean(trainer))
        .map((trainer, idx) => {
            const championName = trainer.championName ?? `Trainer ${idx + 1}`;
            const roleKey = idx < 4 ? 'arenaUi.eliteRoleCouncil' : 'arenaUi.eliteRoleChampion';
            const roleFallback = idx < 4 ? 'Elite Four' : 'Champion';
            const roleLabel = typeof game.t === 'function'
                ? (() => {
                    const out = game.t(roleKey);
                    return out && out !== roleKey ? out : roleFallback;
                })()
                : roleFallback;
            const spriteUrl = typeof game.getEliteFourTrainerSpriteUrl === 'function'
                ? game.getEliteFourTrainerSpriteUrl(championName)
                : '';
            const specialtyType = String(trainer.type ?? 'normal').toLowerCase().trim();

            const team = (trainer.team ?? [])
                .filter((entry): entry is { name: string; level?: number } => Boolean(entry && entry.name))
                .map((entry) => ({
                    name: entry.name,
                    displayName: uiPokemonNameText(game, entry.name) || entry.name,
                    spriteUrl: getPokemonSpriteUrl(entry.name, false, false, {
                        animatedConfig: { all: false, team: false, pension: false },
                    }),
                    level: Number(entry.level) > 0 ? Math.floor(Number(entry.level)) : 50,
                }));

            return {
                championName: localizeTrainerName(championName, game.language),
                roleLabel,
                spriteUrl,
                specialtyType,
                team,
            };
        });
}
