/** PokeAPI flat badge IDs (sprites/badges/{id}.png). Gym order per region. */

import { ELITE_FOURS } from './balance/arenasTrainers/index.ts';
import { getEliteFourTrainerSpriteUrl } from './eliteFourTrainerSprites.ts';

export const BADGE_SPRITES_BY_TALENT: Record<string, number> = {
    resilience: 1,
    vitality: 2,
    fortune: 3,
    wisdom: 4,
    pension: 5,
    prestige: 6,
    power: 7,
    master: 8,
    zephyr: 9,
    hive: 10,
    plain: 11,
    fog: 12,
    storm: 13,
    mineral: 14,
    glacier: 15,
    rising: 16,
    stone: 17,
    knuckle: 18,
    dynamo: 19,
    heat: 20,
    balance: 21,
    feather: 22,
    mind: 23,
    rain: 24,
    coal: 25,
    forest: 26,
    cobble: 27,
    fen: 28,
    relic: 29,
    mine: 30,
    icicle: 31,
    beacon: 32,
    trileaf: 33,
    basic: 34,
    insect: 35,
    bolt: 36,
    quake: 37,
    jet: 38,
    freeze: 39,
    legend: 40,
    bug: 41,
    cliff: 42,
    rumble: 43,
    plant: 44,
    voltage: 45,
    fairy: 46,
    psychic: 47,
    iceberg: 48,
};

const POKEAPI_BADGE_SPRITE_BASE =
    'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/badges';

export function getBadgeSpriteUrl(talentKey: string): string {
    const id = BADGE_SPRITES_BY_TALENT[talentKey];
    if (!id) return '';
    return `${POKEAPI_BADGE_SPRITE_BASE}/${id}.png`;
}

export function isLeagueBadgeKey(talentKey: string): boolean {
    return talentKey.startsWith('maitre_');
}

/** Region abbreviations for league badge fallbacks when champion sprite is unavailable. */
export function getLeagueBadgeFallbackLabel(talentKey: string): string {
    const region = talentKey.replace(/^maitre_/, '');
    const abbrevs: Record<string, string> = {
        kanto: 'KT',
        johto: 'JH',
        hoenn: 'HN',
        sinnoh: 'SN',
        unova: 'UN',
        kalos: 'KL',
        alola: 'AL',
        galar: 'GA',
        paldea: 'PA',
    };
    return abbrevs[region] || region.slice(0, 2).toUpperCase() || 'LG';
}

export function getLeagueChampionName(talentKey: string): string {
    if (!isLeagueBadgeKey(talentKey)) return '';
    const eliteFours = ELITE_FOURS as Record<string, {
        rewardBadge?: string;
        trainers?: Array<{ championName?: string }>;
    }>;
    for (const eliteDef of Object.values(eliteFours)) {
        if (eliteDef?.rewardBadge !== talentKey) continue;
        const trainers = eliteDef.trainers;
        if (!Array.isArray(trainers) || trainers.length === 0) return '';
        const last = trainers[trainers.length - 1];
        return String(last?.championName || '');
    }
    return '';
}

export function getLeagueBadgeSpriteUrl(talentKey: string): string {
    const championName = getLeagueChampionName(talentKey);
    if (!championName) return '';
    return getEliteFourTrainerSpriteUrl(championName);
}
