import type { ArenaPanelUiSnapshot, ArenaSnapshot } from '../bus/snapshots.js';

function uiEqual(a: ArenaPanelUiSnapshot, b: ArenaPanelUiSnapshot): boolean {
  return (
    a.language === b.language
    && a.title === b.title
    && a.subGyms === b.subGyms
    && a.subElite === b.subElite
    && a.subTabsAriaLabel === b.subTabsAriaLabel
  );
}

function eliteFourTrainersEqual(
  a: ArenaSnapshot['eliteFourTrainers'],
  b: ArenaSnapshot['eliteFourTrainers'],
): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    const ta = a[i]!;
    const tb = b[i]!;
    if (
      ta.championName !== tb.championName
      || ta.roleLabel !== tb.roleLabel
      || ta.spriteUrl !== tb.spriteUrl
      || ta.specialtyType !== tb.specialtyType
      || ta.team.length !== tb.team.length
    ) {
      return false;
    }
    for (let j = 0; j < ta.team.length; j++) {
      const pa = ta.team[j]!;
      const pb = tb.team[j]!;
      if (pa.name !== pb.name || pa.level !== pb.level || pa.spriteUrl !== pb.spriteUrl) {
        return false;
      }
    }
  }
  return true;
}

export function arenaSnapshotWouldChange(prev: ArenaSnapshot, next: ArenaSnapshot): boolean {
  return (
    !uiEqual(prev.ui, next.ui)
    || prev.trainerCardTitle !== next.trainerCardTitle
    || prev.badgesHtml !== next.badgesHtml
    || prev.arenasHtml !== next.arenasHtml
    || prev.eliteFourHtml !== next.eliteFourHtml
    || !eliteFourTrainersEqual(prev.eliteFourTrainers, next.eliteFourTrainers)
  );
}
